const { mkdtempSync, readFileSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const { pathToFileURL } = await import("url");
const root = mkdtempSync(join(tmpdir(), "koala-store-"));
try {
  const { StoryStore } = await import(pathToFileURL($root + "/packages/main/dist/core/store.js").href);
  const store = new StoryStore(root);
  const long = "long-desc-" + "x".repeat(20000) + "\nquoted \" text";
  const data = { items: [{ id: "CHK-001", title: "long", status: "pending", startTime: null, endTime: null, testIntent: { happy: [{ desc: long, type: "cli_blackbox" }], edge: [], adversarial: [] } }] };
  store.writeChecklist("B-test", data);
  const raw = readFileSync(join(root, "docs/story/actives/B-test/checklist.json"), "utf8");
  const parsed = JSON.parse(raw);
  return { parseable: true, descLength: parsed.items[0].testIntent.happy[0].desc.length };
} finally { rmSync(root, { recursive: true, force: true }); }

const { mkdtempSync, readFileSync, rmSync } = await import("fs");
