const { mkdtempSync, readFileSync, readdirSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const { pathToFileURL } = await import("url");
const root = mkdtempSync(join(tmpdir(), "koala-store-"));
try {
  const { StoryStore } = await import(pathToFileURL($root + "/packages/main/dist/core/store.js").href);
  const store = new StoryStore(root);
  store.writeChecklist("B-test", { items: [{ id: "CHK-001", title: "safe", status: "pending", startTime: null, endTime: null }] });
  const bad = { items: [] }; bad.self = bad;
  try { store.writeChecklist("B-test", bad); } catch {}
  const dir = join(root, "docs/story/actives/B-test");
  const files = readdirSync(dir);
  const parsed = JSON.parse(readFileSync(join(dir, "checklist.json"), "utf8"));
