} finally { rmSync(root, { recursive: true, force: true }); }

const name = "long-intent-" + Date.now();
const created = await $handlers.story_create({ name, title: "Long intent fixture", description: "fixture", type: "bug", priority: "low", forceNew: true, checklist: [{ title: "item", context: "ctx" }] });
const storyId = created.match(/B-[a-f0-9]+/)[0];
const long = "quoted \" text with newline\n" + "x".repeat(15000);
await $handlers.checklist_update({ storyId, itemId: "CHK-001", testIntent: { happy: [{ desc: long, type: "cli_blackbox" }], edge: [{ desc: "edge", type: "cli_blackbox" }], adversarial: [{ desc: "adv", type: "cli_blackbox" }] }, agent: "test-intent" });
const read = await $handlers.checklist_get({ storyId });
await $handlers.story_discard({ storyId, cleanupResidue: true, confirm: true });
return { len: read.items[0].testIntent.happy[0].desc.length, phase: read.items[0].testIntent.happy[0].type };

