const { readFileSync } = await import("fs");
const { execFileSync } = await import("child_process");
const activity = $root + "/docs/story/activity.jsonl";
const count = () => readFileSync(activity, "utf8").split("\n").filter(Boolean).length;
const before = count();
execFileSync(process.execPath, ["packages/main/dist/cli.js", "story_discard", JSON.stringify({ storyId: "B-0072", dryRun: true })], { cwd: $root, encoding: "utf8" });
const after = count();
return { before, after, stable: before === after };

